 "components": "[{\"id\": \"root\", \"component\": \"Column\", \"gap\": \"md\", \"children\": [\"head\", \"meta\", \"ing_sec\", \"steps_sec\", \"tips\", \"footer\"]}, {\"id\": \"head\", \"component\": \"Heading\", \"text\": \"Kimchi Fried Rice (Kimchi Bokkeumbap)\", \"eyebrow\": \"Recipe · Korean\", \"subtitle\": \"A 20-minute one-pan fried rice made with aged kimchi and its juice.\"}, {\"id\": \"meta\", \"component\": \"Grid\", \"columns\": 3, \"gap\": \"md\", \"children\": [\"m1\", \"m2\", \"m3\"]}, {\"id\": \"m1\", \"component\": \"Stat\", \"label\": \"Prep time\", \"value\": \"5 min\", \"caption\": \"Chop kimchi, prep toppings\", \"tone\": \"default\"}, {\"id\": \"m2\", \"component\": \"Stat\", \"label\": \"Cook time\", \"value\": \"15 min\", \"delta\": \"10 min + 5 min\", \"tone\": \"default\", \"caption\": \"Fry rice, then crisp the bottom\"}, {\"id\": \"m3\", \"component\": \"Stat\", \"label\": \"Total\", \"value\": \"20 min\", \"delta\": \"Serves 2\", \"tone\": \"positive\", \"caption\": \"One pan, one bowl\"}, {\"id\": \"ing_sec\", \"component\": \"Section\", \"title\": \"Ingredients\", \"description\": \"Sour, aged kimchi works best — fresh kimchi tastes flat here.\", \"children\": [\"ing\"]}, {\"id\": \"ing\", \"component\": \"List\", \"direction\": \"vertical\", \"marker\": \"bullet\", \"items\": [{\"label\": \"Day-old cooked short-grain rice\", \"value\": \"400 g (2 cups)\"}, {\"label\": \"Aged kimchi, chopped\", \"value\": \"150 g\"}, {\"label\": \"Kimchi juice\", \"value\": \"2 tbsp\"}, {\"label\": \"Sesame oil\", \"value\": \"1 tbsp\"}, {\"label\": \"Neutral oil\", \"value\": \"1 tbsp\"}, {\"label\": \"Soy sauce\", \"value\": \"1 tbsp\"}, {\"label\": \"Sugar\", \"value\": \"1 tsp\"}, {\"label\": \"Gochugaru (Korean chili flakes)\", \"value\": \"1 tsp\"}, {\"label\": \"Garlic, minced\", \"value\": \"2 cloves\"}, {\"label\": \"Green onion, sliced\", \"value\": \"2 stalks\"}, {\"label\": \"Eggs (for frying on top)\", \"value\": \"2\"}, {\"label\": \"Toasted sesame seeds\", \"value\": \"1 tbsp\"}, {\"label\": \"Optional: Spam or bacon\", \"value\": \"100 g, diced\"}]}, {\"id\": \"steps_sec\", \"component\": \"Section\", \"title\": \"Steps\", \"description\": \"Do not stir until the rice has crisped — that is the whole trick.\", \"children\": [\"steps\"]}, {\"id\": \"steps\", \"component\": \"Timeline\", \"items\": [{\"title\": \"Prep the kimchi\", \"time\": \"2 min\", \"description\": \"Squeeze the kimchi from the jar and chop it into 2 cm pieces. Measure 2 tbsp of the juice.\", \"status\": \"done\"}, {\"title\": \"Fry the aromatics\", \"time\": \"2 min\", \"description\": \"Heat the neutral oil over medium-high. Add the kimchi and garlic, stir-fry until the edges caramelize and smell toasty.\", \"status\": \"current\"}, {\"title\": \"Add the rice\", \"time\": \"5 min\", \"description\": \"Add cold day-old rice and break it apart with the spatula. Add kimchi juice, soy sauce, sugar and gochugaru; toss until every grain is red.\", \"status\": \"upcoming\"}, {\"title\": \"Crisp the bottom\", \"time\": \"5 min\", \"description\": \"Stop stirring. Press the rice flat, drizzle the sesame oil around the edge, and let it sizzle undisturbed until the bottom crackles.\", \"status\": \"upcoming\"}, {\"title\": \"Egg and finish\", \"time\": \"3 min\", \"description\": \"Push the rice to one side, crack in the eggs and fry until the edges are lacy. Fold over the rice, scatter green onion and sesame seeds.\", \"status\": \"upcoming\"}, {\"title\": \"Serve\", \"time\": \"1 min\", \"description\": \"Split into two bowls. A drizzle of sesame oil and a sheet of nori on top, if you like.\", \"status\": \"upcoming\"}]}, {\"id\": \"tips\", \"component\": \"Callout\", \"title\": \"Two things that decide the dish\", \"icon\": \"chef-hat\", \"text\": \"Use **cold, day-old rice** — fresh rice steams and turns gummy. And **do not stir** during the last 5 minutes; the crackling crust is the best part.\"}, {\"id\": \"footer\", \"component\": \"Caption\", \"text\": \"Quantities are for 2 servings. Illustrative recipe card.\"}, {\"id\": \"follow\", \"component\": \"FollowUp\", \"items\": [\"Show a vegetarian version\", \"What can I swap for gochugaru?\", \"Scale this to 4 servings\"]}]}",
 "data": {
  "recipe": "kimchi-fried-rice",
  "servings": 2
 }
}
